{
  "model": "vertex/gemini-3.7-flash",
  "max_tokens": 64,
  "tools": [
    {
      "name": "read_file",
      "description": "Read a file",
      "input_schema": {
        "type": "object",
        "properties": {
          "path": {
            "type": "string"
          }
        },
        "required": [
          "path"
        ]
      }
    }
  ],
  "messages": [
    {
      "role": "user",
      "content": "Read a.txt and b.txt and tell me which file says what."
    },
    {
      "role": "assistant",
      "content": [
        {
          "type": "tool_use",
          "id": "toolu_a",
          "name": "read_file",
          "input": {
            "path": "a.txt"
          }
        },
        {
          "type": "tool_use",
          "id": "toolu_b",
          "name": "read_file",
          "input": {
            "path": "b.txt"
          }
        }
      ]
    },
    {
      "role": "user",
      "content": [
        {
          "type": "tool_result",
          "tool_use_id": "toolu_b",
          "content": "contents of B"
        },
        {
          "type": "tool_result",
          "tool_use_id": "toolu_a",
          "content": "contents of A"
        }
      ]
    }
  ]
}

